// 1. Извлекаем список страниц Confluence со всех страниц пагинации
const confPages = [];
for (const item of $('Поиск страниц по разделу').all()) {
  const res = item.json.results || [];
  confPages.push(...res);
}

// 2. Извлекаем существующие точки из Qdrant
let qdrantPoints = [];
try {
  const qdrantNode = $('Qdrant - Считать версии').first();
  qdrantPoints = qdrantNode.json.result?.points || qdrantNode.json.points || [];
  if (!Array.isArray(qdrantPoints) && $('Qdrant - Считать версии').all().length > 0) {
    qdrantPoints = $('Qdrant - Считать версии').all().map(i => i.json);
  }
} catch (e) {
  qdrantPoints = [];
}

// 3. Строим карту существующих версий в Qdrant: { [pageId]: maxVersion }
const existingVersions = {};
for (const pt of qdrantPoints) {
  const m = pt.payload?.metadata || pt.metadata || pt.payload;
  if (m && m.pageId) {
    const pId = String(m.pageId);
    const v = Number(m.version) || 0;
    if (!existingVersions[pId] || v > existingVersions[pId]) {
      existingVersions[pId] = v;
    }
  }
}

// 4. Находим страницы, которые новые или изменились (с дедупликацией)
const seenIds = new Set();
const pagesToUpdate = [];

for (const page of confPages) {
  const pId = String(page.id);
  if (seenIds.has(pId)) continue;
  seenIds.add(pId);

  const currentVersion = Number(page.version?.number) || 1;
  const inQdrantVersion = existingVersions[pId];

  // Страница новая ИЛИ ее версия в Confluence выше, чем в Qdrant
  if (inQdrantVersion === undefined || currentVersion > inQdrantVersion) {
    pagesToUpdate.push({
      json: {
        pageId: pId,
        title: page.title,
        version: currentVersion,
        oldVersion: inQdrantVersion || 0,
        isNew: inQdrantVersion === undefined,
        pageData: page
      }
    });
  }
}

return pagesToUpdate;

const items = [];
const baseUrl = $('Настройки').first().json.confluenceBaseUrl.replace(/\/wiki\/?$/, '');
const spaceKey = $('Настройки').first().json.spaceKey || '~70121c7daeab8fb0d42e5a9d66704bad7c375';

function stringToUUID(str) {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    hash = ((hash << 5) - hash) + str.charCodeAt(i);
    hash |= 0;
  }
  const hex = Math.abs(hash).toString(16).padStart(32, '0');
  return `${hex.slice(0,8)}-${hex.slice(8,12)}-4${hex.slice(13,16)}-a${hex.slice(17,20)}-${hex.slice(20,32)}`;
}

function htmlToMarkdownWithInlineMedia(html, pageId, captions = {}) {
  if (!html) return '';

  let cleanHtml = html;

  // 1. Очистка пустых заголовков (включая пробелы и &nbsp;)
  cleanHtml = cleanHtml.replace(/<h[1-6][^>]*>(?:\s|&nbsp;|<[^>]+>)*<\/h[1-6]>/gi, (match) => {
    const inner = match.replace(/<[^>]+>/g, '').replace(/&nbsp;/g, ' ').trim();
    return inner ? match : '';
  });

  // 2. Заголовки внутри ячеек таблиц (th/td) переводим в strong, чтобы не рвать строки таблицы
  cleanHtml = cleanHtml.replace(/<(td|th)([^>]*)>([\s\S]*?)<\/\1>/gi, (match, tag, attrs, content) => {
    const cleanContent = content.replace(/<h[1-6][^>]*>([\s\S]*?)<\/h[1-6]>/gi, '<strong>$1</strong>');
    return `<${tag}${attrs}>${cleanContent}</${tag}>`;
  });

  return cleanHtml
    .replace(/<ac:image([^>]*)>[\s\S]*?ri:filename=["']([^"']+)["'][\s\S]*?<\/ac:image>/gi, (match, attrs, filename) => {
      let captionText = captions[filename];
      if (!captionText) {
        const altMatch = attrs.match(/ac:(?:alt|title)=["']([^"']+)["']/i);
        if (altMatch) captionText = altMatch[1];
      }
      const caption = captionText ? ` (${captionText.trim()})` : '';
      const url = `${baseUrl}/wiki/download/attachments/${pageId}/${encodeURIComponent(filename)}`;
      return `\n\n🖼 [Изображение: ${filename}${caption}](${url})\n\n`;
    })
    .replace(/<img\s+[^>]*src=["']([^"']+)["'][^>]*>/gi, (match, src) => {
      let fullUrl = src.startsWith('/') ? baseUrl + src : src;
      return `\n\n🖼 [Изображение](${fullUrl})\n\n`;
    })
    .replace(/<h[1-3][^>]*>(.*?)<\/h[1-3]>/gi, '\n\n## $1\n\n')
    .replace(/<h[4-6][^>]*>(.*?)<\/h[4-6]>/gi, '\n\n### $1\n\n')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n\n')
    .replace(/<\/li>/gi, '\n')
    .replace(/<tr[^>]*>/gi, '\n')
    .replace(/<\/td>|<\/th>/gi, ' | ')
    .replace(/<[^>]+>/g, '')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&nbsp;/g, ' ')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&laquo;/g, '«')
    .replace(/&raquo;/g, '»')
    .replace(/\r\n/g, '\n')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n\s*\n\s*\n+/g, '\n\n')
    .trim();
}

function splitIntoSemanticSections(title, fullText, pageUrl, pageId, maxLen = 1800, overlap = 300) {
  // Нарезка по заголовкам ## и ###
  const rawSections = fullText.split(/\n(?=#{2,3}\s)/).map(s => s.trim()).filter(Boolean);

  // Механизм слияния микросекций (Micro-chunk Merging): секции < 150 символов склеиваются
  const mergedSections = [];
  let buffer = '';

  for (let i = 0; i < rawSections.length; i++) {
    const sec = rawSections[i];
    if (!buffer) {
      buffer = sec;
    } else {
      buffer += '\n\n' + sec;
    }

    if (buffer.length >= 150 && i < rawSections.length - 1) {
      mergedSections.push(buffer);
      buffer = '';
    }
  }

  if (buffer) {
    if (buffer.length < 150 && mergedSections.length > 0) {
      mergedSections[mergedSections.length - 1] += '\n\n' + buffer;
    } else {
      mergedSections.push(buffer);
    }
  }

  const result = [];

  for (let idx = 0; idx < mergedSections.length; idx++) {
    const sec = mergedSections[idx].trim();
    if (!sec || sec.length < 20) continue;

    const headerMatch = sec.match(/^(#{2,3}\s+[^\n]+)/);
    const secHeader = headerMatch ? headerMatch[1].trim() : `Раздел ${idx + 1}`;

    if (sec.length <= maxLen) {
      result.push({
        text: `ДОКУМЕНТ: ${title}\n\n${sec}\n\nИсточник: ${pageUrl}\nСтатья: ${title}`,
        chunkIdx: idx
      });
    } else {
      const paras = sec.split(/\n\n+/).map(p => p.trim()).filter(Boolean);
      let subIdx = 0;
      let partNum = 1;
      let curParas = [];
      let curLen = 0;
      const prefixBase = `ДОКУМЕНТ: ${title}\nРАЗДЕЛ: ${secHeader}`;

      for (let i = 0; i < paras.length; i++) {
        const p = paras[i];
        const prefix = partNum > 1 ? `${prefixBase} (Часть ${partNum})\n\n` : `ДОКУМЕНТ: ${title}\n\n`;
        const testLen = prefix.length + curLen + p.length + 2;

        if (testLen <= maxLen || curParas.length === 0) {
          curParas.push(p);
          curLen += p.length + 2;
        } else {
          const chunkBody = curParas.join('\n\n');
          result.push({
            text: `${prefix}${chunkBody}\n\nИсточник: ${pageUrl}\nСтатья: ${title}`,
            chunkIdx: `${idx}_${subIdx++}`
          });
          partNum++;

          const overlapParas = [];
          let accLen = 0;
          for (let j = curParas.length - 1; j >= 0; j--) {
            const prevP = curParas[j];
            if (accLen + prevP.length <= overlap) {
              overlapParas.unshift(prevP);
              accLen += prevP.length + 2;
            } else {
              if (overlapParas.length === 0) {
                const sliceText = prevP.slice(-overlap).trim();
                if (sliceText) overlapParas.push('... ' + sliceText);
              }
              break;
            }
          }
          curParas = overlapParas.concat([p]);
          curLen = curParas.reduce((acc, x) => acc + x.length + 2, 0);
        }
      }

      if (curParas.length > 0) {
        const prefix = partNum > 1 ? `${prefixBase} (Часть ${partNum})\n\n` : `ДОКУМЕНТ: ${title}\n\n`;
        const chunkBody = curParas.join('\n\n');
        result.push({
          text: `${prefix}${chunkBody}\n\nИсточник: ${pageUrl}\nСтатья: ${title}`,
          chunkIdx: `${idx}_${subIdx}`
        });
      }
    }
  }

  if (result.length === 0 && fullText.trim()) {
    result.push({
      text: `ДОКУМЕНТ: ${title}\n\n${fullText.trim()}\n\nИсточник: ${pageUrl}\nСтатья: ${title}`,
      chunkIdx: 0
    });
  }
  return result;
}

const seenChunks = new Set();
const inputItems = $('Детектор изменений').all();

for (const item of inputItems) {
  const page = item.json.pageData;
  if (!page) continue;

  const html = page.body?.storage?.value || '';
  const pageUrl = `${baseUrl}/wiki/spaces/${spaceKey}/pages/${page.id}`;
  const captions = page.metadata?.properties?.media_captions?.value || {};

  let formattedText = htmlToMarkdownWithInlineMedia(html, page.id, captions);
  if (!formattedText || formattedText.length < 20) {
    formattedText = 'Раздел в разработке (пустая страница в Confluence).';
  }

  const chunks = splitIntoSemanticSections(page.title, formattedText, pageUrl, page.id, 1800, 300);

  chunks.forEach(({ text, chunkIdx }) => {
    if (seenChunks.has(text)) return;
    seenChunks.add(text);

    const deterministicId = stringToUUID(`confluence_${page.id}_chunk_${chunkIdx}`);

    items.push({
      json: {
        pageContent: text,
        id: deterministicId,
        pageId: String(page.id),
        metadata: {
          id: deterministicId,
          pageId: String(page.id),
          version: Number(page.version?.number) || 1,
          title: page.title,
          url: pageUrl
        }
      }
    });
  });
}

return items;
